    crate::chat::ChatStreamEvent { req_id: req.into(), conversation_id: conv.map(str::to_owned), kind: kind.into(), text, tool: None }
}
//! UI delivery reuses the existing prompt assembly, artifact diff and persistence.
use super::*;
use crate::chat::ChatStreamEvent;
