    const text = pendingDelta[cid];
    if (text) {
      delete pendingDelta[cid];
      appendDelta(cid, text);
    }
  }
  function flushAllDeltas() {
    deltaTimer = null;
    for (const cid of Object.keys(pendingDelta)) flushDelta(cid);
  }
